(() => {
  const $ = s => document.querySelector(s);
  const entries = [
    ['χρυσοῦς','circumflex','Simple -ους: circumflex','The passage gives χρύσὲὸς → χρυσοῦς: the simple -ους rule prevails over the contraction argument.'],
    ['ἀργυροῦς','circumflex','Simple -ους: circumflex','The passage pairs ἀργύρὲὸς → ἀργυροῦς with χρυσοῦς.'],
    ['ἀδελφιδοῦς','circumflex','Simple -ους: circumflex','ἀδελφιδὲός → ἀδελφιδοῦς is listed under the same -ους rule.'],
    ['θυγατριδοῦς','circumflex','Simple -ους: circumflex','θυγατριδὲός → θυγατριδοῦς is listed under the same -ους rule.'],
    ['ὑϊδοῦς','circumflex','Simple -ους: circumflex','ὑϊδοῦς is another circumflexed example explicitly listed in the passage.'],
    ['τηθαλλαδοῦς','circumflex','Simple -ους: circumflex','τηθαλλαδοῦς is listed under the same rule despite the contraction argument.'],
    ['ὀδούς','acute','Exception: acute on the last syllable','The passage calls ὀδούς exceptional. It follows participles in accent and declension: ὀδούς, ὀδόντος like διδοὺς, διδόντος. The Ionic variant is ὀδών.'],
    ['Πειρίθους','barytone','Compound: barytone','Πειρίθους appears in the passage’s list of compounds whose accent is not on the last syllable.'],
    ['Ἀλκίνους','barytone','Compound: barytone','Ἀλκίνους appears in the barytone compound list.'],
    ['εὔπλους','barytone','Compound: barytone','εὔπλους appears in the barytone compound list.'],
    ['πολύνους','barytone','Compound: barytone','πολύνους appears in the barytone compound list.'],
    ['Οἰδίπους','barytone','Compound: barytone','Οἰδίπους appears in the barytone compound list.'],
    ['Μελάμπους','barytone','Compound: barytone','Μελάμπους appears in the barytone compound list.'],
    ['ἐΰξους','barytone','Compound: barytone','ἐΰξους appears in the barytone compound list.'],
    ['εὔνους','barytone','Compound: barytone','εὔνους appears in the barytone compound list.'],
    ['σύννους','barytone','Compound: barytone','σύννους appears in the barytone compound list.'],
    ['Δημοσθένους','barytone','Contraction comparison: barytone','Δημοσθένὲὸς → Δημοσθένους illustrates the contraction argument. This comparison is not one of the listed compounds.']
  ];
  const key = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/σ$/,'ς');
  const examples = new Map(entries.map(e => [key(e[0]),e]));
  let selected = null;
  function explore(){
    selected = examples.get(key($('#word').value)) || null;
    $('#feedback').textContent = '';
    $('#quiz').hidden = !selected;
    $('#spelling').textContent = selected ? selected[0] : ($('#word').value.trim() ? 'Example not listed' : 'Choose an example');
    $('#category').textContent = selected ? selected[2] : '';
    $('#reason').textContent = selected ? selected[3] : ($('#word').value.trim() ? 'No prediction: try an example from passage 1.243.' : 'Enter a Greek example to explore the rule and its exceptions.');
  }
  $('#lookup').addEventListener('submit',e=>{e.preventDefault();explore();});
  $('#clear').addEventListener('click',()=>{$('#word').value='';explore();$('#word').focus();});
  document.querySelectorAll('[data-word]').forEach(b=>b.addEventListener('click',()=>{$('#word').value=b.dataset.word;explore();}));
  document.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>{
    if(selected) $('#feedback').textContent = b.dataset.answer === selected[1] ? 'Correct — '+selected[2]+'.' : 'Try again — '+selected[2]+'.';
  }));
  explore();
})();

