:root{
  --bg:#0f1220;
  --panel:#171b2e;
  --panel2:#12162a;
  --text:#e9ecff;
  --muted:#b8c0ff;
  --line:#2a3158;
  --accent:#7dd3fc;
  --good:#86efac;
  --bad:#fb7185;
  --warn:#fbbf24;
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1a2150 0%, var(--bg) 55%);color:var(--text);font:15px/1.35 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}
.wrap{max-width:980px;margin:0 auto;padding:18px}
.hdr{display:flex;gap:14px;align-items:flex-start;margin-bottom:14px}
h1{font-size:20px;margin:0 0 6px 0;letter-spacing:.2px}
.sub{margin:0;color:var(--muted)}
.panel{background:linear-gradient(180deg,var(--panel),var(--panel2));border:1px solid var(--line);border-radius:14px;padding:14px;margin:12px 0;box-shadow:0 10px 30px rgba(0,0,0,.25)}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.row.small{margin-top:8px}
.lab{min-width:92px;color:var(--muted)}
.inp{flex:1;min-width:240px;padding:10px 12px;border-radius:12px;border:1px solid var(--line);background:#0c1022;color:var(--text);outline:none}
.inp:focus{border-color:rgba(125,211,252,.7);box-shadow:0 0 0 3px rgba(125,211,252,.15)}
.btn{padding:10px 12px;border-radius:12px;border:1px solid rgba(125,211,252,.35);background:rgba(125,211,252,.12);color:var(--text);cursor:pointer}
.btn:hover{background:rgba(125,211,252,.18)}
.btn:active{transform:translateY(1px)}
.btn.ghost{border-color:var(--line);background:transparent;color:var(--muted)}
.btn.ghost:hover{background:rgba(255,255,255,.04);color:var(--text)}
.tog{display:flex;gap:8px;align-items:center;color:var(--muted)}
.tog input{accent-color:var(--accent)}
.out{margin-top:12px;padding:12px;border-radius:12px;border:1px dashed rgba(125,211,252,.35);background:rgba(0,0,0,.18)}
.kv{display:grid;grid-template-columns:160px 1fr;gap:6px 12px;margin:0}
.k{color:var(--muted)}
.v{color:var(--text)}
.badge{display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid var(--line);background:rgba(255,255,255,.04);margin-left:8px;color:var(--muted);font-size:12px}
.badge.good{border-color:rgba(134,239,172,.35);color:var(--good)}
.badge.bad{border-color:rgba(251,113,133,.35);color:var(--bad)}
.badge.warn{border-color:rgba(251,191,36,.35);color:var(--warn)}
.rules summary{cursor:pointer;color:var(--accent)}
.rules ul{margin:10px 0 0 18px;color:var(--muted)}
.note{color:var(--muted);margin:10px 0 0 0}
.game{display:grid;grid-template-columns:1fr;gap:12px;margin-top:10px}
.bank{display:flex;flex-wrap:wrap;gap:8px;padding:10px;border-radius:12px;border:1px solid var(--line);background:rgba(0,0,0,.12);min-height:54px}
.chip{user-select:none;cursor:grab;padding:7px 10px;border-radius:999px;border:1px solid rgba(125,211,252,.25);background:rgba(125,211,252,.10);color:var(--text);font-variant-ligatures:none}
.chip:active{cursor:grabbing}
.bins{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.bin{border-radius:14px;border:1px solid var(--line);background:rgba(0,0,0,.10);min-height:120px;display:flex;flex-direction:column;outline:none}
.bin:focus{box-shadow:0 0 0 3px rgba(125,211,252,.15)}
.binTitle{padding:10px 12px;border-bottom:1px solid var(--line);color:var(--muted)}
.binBody{padding:10px;display:flex;flex-wrap:wrap;gap:8px;min-height:70px}
.bin.dragover{border-color:rgba(125,211,252,.7);background:rgba(125,211,252,.08)}
.score{color:var(--muted)}
.ftr{color:var(--muted);margin-top:10px}
@media (max-width:720px){
  .kv{grid-template-columns:1fr}
  .bins{grid-template-columns:1fr}
  .lab{min-width:auto}
}
.inp{min-width:0;max-width:100%}.kv dd{margin:0;overflow-wrap:anywhere}.chip[aria-pressed="true"]{outline:3px solid #fbbf24}.chip{font:inherit}.out{overflow-wrap:anywhere}select.inp{flex:1}button{max-width:100%;white-space:normal}.binTitle{overflow-wrap:anywhere}

