(() => {
 const $ = s => document.querySelector(s);
 const $$ = s => Array.from(document.querySelectorAll(s));
 const rows = [];
 function add(words,target,sense,rule){words.split(' ').forEach(word=>rows.push({word,target,sense,rule}));}
 add('Γιλγάμης Ἰάμης Ἀδρύμης','bary','noun','The passage lists -μης forms as barytone.');
 add('Τιγράνης Ἰορδάνης Ἐξοστάνης Ἀϊάνης Βαρδάνης Ἀριστοφάνης Θεοφάνης','bary','noun','The proper names in -ανης are barytone.');
 add('Ὀρθάννης Βαστάρνης Ἀρταφέρνης Ἰνταφέρνης','bary','noun','This form is explicitly listed among the barytone examples.');
 add('Δημοσθένης Διογένης Ἀντιγένης Ἀριστομένης Βορυσθένης','bary','noun','The proper names in -ενης are barytone.');
 add('ἀμένης','bary','noun','The passage gives ἀμένης, ἀμένητος: “the child”.');
 add('θεοφανής','oxy','adjective','The adjective θεοφανής is oxytone, unlike the name Θεοφάνης.');
 add('ἀμενής εὐμενής δυσμενής ἀγενής','oxy','adjective','These -ενης adjectives are oxytone, unlike the proper names.');
 add('σαφηνής παιδηνής γαληνής δυσδηνής ἀπηνής προσηνής δυσηνής','oxy','adjective','This is one of the oxytone forms listed in the -ηνης section.');
 add('ἀμελής ἀφελής ἀελλής ἀολλής','oxy','adjective','The passage prints this adjective with final acute and gives a genitive ending in -ους.');
 const key = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/σ$/,'ς');
 const pitch = s => s.normalize('NFD').replace(/\u0300/g,'\u0301').replace(/[\u0308\u0313\u0314\u0345]/g,'').toLowerCase().trim();
 const label = r => r.target === 'bary' ? 'Barytone (not final-accented)' : 'Oxytone (acute on the last syllable)';
 function readings(raw,sense){
  let found = rows.filter(r=>key(r.word)===key(raw));
  if(found.length>1){
   if(sense!=='auto') found=found.filter(r=>r.sense===sense);
   else {const exact=found.filter(r=>pitch(r.word)===pitch(raw));if(exact.length)found=exact;}
  }
  return found;
 }
 function analyze(){
  const raw=$('#inp').value.trim(),found=readings(raw,$('#sense').value),out=$('#out');out.replaceChildren();
  if(!raw || !found.length){out.textContent=!raw?'Type a Greek word first.':'Not in this passage’s example set. No accent or genitive generated.';return;}
  if(found.length>1){const p=document.createElement('p');p.textContent='Two readings — choose a sense or type the accent.';out.append(p);}
  found.forEach(r=>{
   const h=document.createElement('h3');h.textContent=r.word;h.lang='grc';
   const p=document.createElement('p');p.textContent=label(r);
   const note=document.createElement('p');note.textContent=r.rule;
   out.append(h,p,note);
  });
 }
 let selected=null;
 function selectChip(chip){
  $$('.chip').forEach(c=>c.setAttribute('aria-pressed',String(c===chip)));
  selected=chip;$('#selection').textContent='Selected: '+chip.textContent+'. Activate a bin.';
 }
 function moveTo(bin){
  if(!selected)return;
  bin.querySelector('.binBody').append(selected);selected.setAttribute('aria-pressed','false');selected=null;
  $('#selection').textContent='Word moved. Check your sorting.';$('#score').textContent='';
 }
 function makeChip(r,i){
  const c=document.createElement('button');c.type='button';c.className='chip';c.draggable=true;c.textContent=r.word;c.dataset.word=r.word;c.dataset.answer=r.target;c.id='chip_'+i;c.setAttribute('aria-pressed','false');
  c.addEventListener('click',e=>{e.stopPropagation();selectChip(c);});
  c.addEventListener('dragstart',e=>{selectChip(c);e.dataTransfer.setData('text/plain',c.id);});return c;
 }
 $$('.bin').forEach(bin=>{
  bin.addEventListener('click',()=>moveTo(bin));
  bin.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target===bin){e.preventDefault();moveTo(bin);}});
  bin.addEventListener('dragover',e=>e.preventDefault());
  bin.addEventListener('drop',e=>{e.preventDefault();const c=document.getElementById(e.dataTransfer.getData('text/plain'));if(c&&c.classList.contains('chip')){selected=c;moveTo(bin);}});
 });
 function resetGame(){
  selected=null;['#bank','#binBary','#binOxy'].forEach(s=>$(s).replaceChildren());$('#selection').textContent='';$('#score').textContent='';
  const pool=[...rows];for(let i=0;i<10;i++){const r=pool.splice(Math.floor(Math.random()*pool.length),1)[0];$('#bank').append(makeChip(r,i));}
 }
 $('#btnCheck').addEventListener('click',()=>{
  let placed=0,correct=0;
  $$('.chip').forEach(c=>{const actual=$('#binBary').contains(c)?'bary':$('#binOxy').contains(c)?'oxy':null;
   c.style.borderColor='';if(actual){placed++;const ok=actual===c.dataset.answer;if(ok)correct++;c.style.borderColor=ok?'#86efac':'#fb7185';}
  });$('#score').textContent='Placed: '+placed+'/10 · Correct: '+correct;
 });
 $('#btnAnalyze').addEventListener('click',analyze);
 $('#inp').addEventListener('keydown',e=>{if(e.key==='Enter')analyze();});$('#sense').addEventListener('change',analyze);
 $('#btnClear').addEventListener('click',()=>{$('#inp').value='';$('#sense').value='auto';$('#out').textContent='';$('#inp').focus();});
 $('#btnRandom').addEventListener('click',()=>{$('#inp').value=rows[Math.floor(Math.random()*rows.length)].word;$('#sense').value='auto';analyze();});
 $('#btnReset').addEventListener('click',resetGame);
 $('#inp').value='Δημοσθένης';analyze();resetGame();
})();

